import {esc,fmt} from '../../ui/format.js';
import {PROCESS,effective} from '../../core/model.js';
import {calibrationIssues} from '../../core/provenance.js';
export function overviewView({m,result,role,baseline}){
 const ops=m.nodes.filter(n=>PROCESS.includes(n.type)),issues=calibrationIssues(m),r=result?.first;
 const ranked=[...(r?.operations||[])].sort((a,b)=>b.resourceWait+b.materialWait-a.resourceWait-a.materialWait).slice(0,5);
 const steps=[['01','Configurează fabrica','Adaugă echipamente și oameni din bibliotecă.','library'],['02','Desenează fluxul','Conectează obiectele și alocă resursele.','diagrams'],['03','Calibrează și compară','Folosește datele măsurate, apoi simulează.','scenarios']];
 return `<section class="page-intro"><div><div class="eyebrow">${role==='management'?'DECIZII OPERAȚIONALE':'SPAȚIUL TĂU DE LUCRU'}</div><h1>Fabrica, într-o singură privire.</h1><p>De la resurse și fluxuri la capacitate și decizii.</p></div><button class="primary" data-page="diagrams">Deschide modelul ↗</button></section><div class="context-strip"><span class="status-dot"></span><b>${esc(m.name)}</b><span>Model de analiză · fără date live</span><button data-action="rename-model">Redenumește</button></div><div class="stats">${[['Operații în model',ops.length,'Definite în repository'],['Producție simulată',r?fmt(result.mean,0):'—',r?'Medie / '+m.settings.hours+' ore':'Rulează primul scenariu'],['WIP la final',r?fmt(r.wip,0):'—','Piese în lucru · prima replicare'],['Parametri de calibrat',issues.length,issues.length?'Date de proces necesare':'Verifică și ipotezele existente']].map(([label,value,sub])=>`<article class="stat"><span>${label}</span><strong class="value">${value}</strong><small>${sub}</small></article>`).join('')}</div><div class="overview-grid"><section class="panel"><div class="panelhead"><div><span class="eyebrow">PRIORITĂȚI</span><h2>Unde se pierde timpul?</h2></div><button data-page="results">Vezi analiza →</button></div>${r?ranked.map((o,i)=>`<div class="rank-row"><span class="rank-index">0${i+1}</span><div><b>${esc(o.name)}</b><div class="small muted">Resurse ${fmt(o.resourceWait/60)} min · material ${fmt(o.materialWait/60)} min</div><div class="metric-track"><i style="width:${Math.min(100,(o.resourceWait+o.materialWait)/(m.settings.hours*3600)*100)}%"></i></div></div><button data-open="${esc(o.id)}">Analizează</button></div>`).join(''):`<div class="empty-illustration"><svg viewBox="0 0 260 90" aria-hidden="true"><path d="M30 45H230" stroke="#b9d7ce" stroke-width="3"/><rect x="10" y="20" width="55" height="50" rx="10" fill="#e0eee7"/><rect x="102" y="10" width="56" height="70" rx="10" fill="#176b59"/><rect x="195" y="20" width="55" height="50" rx="10" fill="#e0eee7"/><path d="M123 31L141 45L123 59Z" fill="#d1f4ad"/></svg><h3>Modelul este gata de explorat</h3><p>O simulare evidențiază cozile și competiția pentru resurse.</p><button class="primary" data-action="run">▷ Rulează simularea</button></div>`}<p class="small muted">Prioritizare după așteptarea în coadă. Confirmă un bottleneck printr-un scenariu comparativ.</p></section><aside class="panel next-panel"><span class="eyebrow">URMĂTORUL PAS</span><h2>${issues.length?'Îmbunătățește datele de intrare':'Construiește o comparație utilă'}</h2><p>${issues.length?`${issues.length} parametri sunt marcați ca necesitând calibrare. Specificația utilajului nu determină automat ciclul produsului.`:'Salvează rezultatul de referință, apoi schimbă o singură variabilă.'}</p><button data-page="${issues.length?'calibration':'scenarios'}">${issues.length?'Deschide calibrarea':'Compară scenarii'} →</button><hr><h3>Calitatea analizei</h3><p class="small">${r?`${result.runs.length} replicări · IC 95% ${result.ci95==null?'indisponibil': '± '+fmt(result.ci95)} produse`:'Niciun rezultat în această sesiune.'}</p><p class="small">${baseline?'Baseline disponibil pentru comparație.':'Baseline nesalvat.'}</p></aside></div><div class="journey">${steps.map(([no,title,body,page])=>`<button data-page="${page}"><span>${no}</span><div><b>${title}</b><p>${body}</p></div><em>↗</em></button>`).join('')}</div>`;
}
